const GAP_PHRASE = "i don't have that information";
const SUPPORT_EMAIL = 'YOUR_SUPPORT_EMAIL';
// AI disclosure, put in front of the first reply of a session by this code (not by the model).
const AI_DISCLOSURE = 'YOUR_AI_DISCLOSURE';
const MAX_LENGTH = 700;
let reply = $input.first().json.output || '';
const question = $('Validate Input').item.json.message || '';
const sessionId = $('Validate Input').item.json.sessionId || '';
const isFirstMessage = $('Validate Input').item.json.is_first_message !== false;

function cleanWidgetReply(value) {
  let text = String(value || '').trim();

  // Output guardrail for the chat widget: plain text only, at most 3 paragraphs.
  text = text
    .replace(/```[\s\S]*?```/g, '')
    .replace(/^\s*#{1,6}\s+/gm, '')
    .replace(/\*\*/g, '')
    .replace(/\*/g, '')
    .replace(/[\u2022\u00b7]/g, '')
    .replace(/[\u2013\u2014]/g, ', ')
    .replace(/^\s*[-+]\s+/gm, '')
    .replace(/^\s*\d+[.)]\s+/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]{2,}/g, ' ')
    .trim();

  text = text.split(/\n\s*\n/).map(p => p.trim()).filter(Boolean).slice(0, 3).join('\n\n');

  if (text.length > MAX_LENGTH) {
    const cut = text.slice(0, MAX_LENGTH);
    const lastStop = Math.max(cut.lastIndexOf('.'), cut.lastIndexOf('?'), cut.lastIndexOf('!'));
    text = (lastStop > 320 ? cut.slice(0, lastStop + 1) : cut).trim();
  }

  return text || ('Sorry, I could not put together a clear answer. Please write to ' + SUPPORT_EMAIL + ' and a person will help.');
}

reply = cleanWidgetReply(reply);

// Log only real knowledge gaps: the agent used the exact gap sentence from its prompt,
// or the cleanup had to fall back. Routing to support or a failed order lookup is not a gap.
const lower = reply.toLowerCase();
const is_no_answer = lower.includes(GAP_PHRASE) || lower.includes('could not put together a clear answer');

// The gap check above runs on the model's own text. The disclosure is added afterwards, once per session.
const output = isFirstMessage && AI_DISCLOSURE ? AI_DISCLOSURE + ' ' + reply : reply;

return [{ json: { output, question, sessionId, is_no_answer } }];

// Input guard: message must be a non-empty string of at most MAX_MESSAGE_LENGTH characters,
// and the widget must send a random session id (UUID). No fallback to email or IP.
const MAX_MESSAGE_LENGTH = 1000;
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const body = $input.first().json.body || {};
const message = typeof body.message === 'string' ? body.message.trim() : '';
const sessionId = typeof body.sessionId === 'string' ? body.sessionId.trim() : '';
let error = '';
if (!message) error = 'message_required';
else if (message.length > MAX_MESSAGE_LENGTH) error = 'message_too_long';
else if (!UUID_RE.test(sessionId)) error = 'session_id_required';
// isFirstMessage is sent by the widget: true on the first message of a session, false afterwards.
// If it is missing, the AI disclosure is added to every reply (the safe default).
const isFirstMessage = !(body.isFirstMessage === false || body.isFirstMessage === 'false');
return [{ json: { valid: error === '', error, message, sessionId, is_first_message: isFirstMessage } }];
